CREATE OR REPLACE FUNCTION public.author_metrics(_month date DEFAULT date_trunc('month',now())::date) RETURNS TABLE(fund_type text,owner_id uuid,course_id uuid,title text,eligible_minutes numeric,approved_minutes numeric,completion numeric,audience numeric,production numeric,score numeric,estimated_cents bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH settings AS(SELECT audience_weight,production_weight,completion_weight FROM public.fund_settings), revenue AS(SELECT COALESCE(sum(amount_cents),0)::numeric total FROM public.payments WHERE status='pago' AND paid_at>=_month AND paid_at<(_month+interval '1 month')),
daily AS(SELECT v.user_id,v.lesson_id,v.viewed_on,least(sum(v.seconds_watched) FILTER(WHERE v.seconds_watched>=20),max(l.duration_min)*60) seconds FROM public.lesson_views v JOIN public.lessons l ON l.id=v.lesson_id WHERE v.viewed_on>=_month AND v.viewed_on<(_month+interval '1 month') GROUP BY v.user_id,v.lesson_id,v.viewed_on),
viewed AS(SELECT d.lesson_id,sum(d.seconds)/60.0 minutes FROM daily d GROUP BY d.lesson_id HAVING sum(d.seconds)>0),
base AS(SELECT CASE WHEN c.institution_id IS NULL THEN 'professor' ELSE 'ies' END kind,COALESCE(c.institution_id,c.instructor_id) owner,c.id cid,c.title heading,COALESCE(sum(v.minutes),0) watched,COALESCE(sum(l.duration_min) FILTER(WHERE v.lesson_id IS NOT NULL),0)::numeric produced FROM public.courses c JOIN public.lessons l ON l.course_id=c.id LEFT JOIN viewed v ON v.lesson_id=l.id WHERE c.status='publicado' AND c.published AND (c.institution_id IS NOT NULL OR c.instructor_id IS NOT NULL) GROUP BY c.id),
completion_rates AS(SELECT cm.course_id cid,COALESCE(count(DISTINCT a.user_id) FILTER(WHERE a.passed)::numeric/NULLIF(count(DISTINCT a.user_id),0),0) completed FROM public.course_modules cm LEFT JOIN public.assessment_attempts a ON a.module_id=cm.id GROUP BY cm.course_id),
totals AS(SELECT kind,sum(watched) watched,sum(produced) produced FROM base GROUP BY kind),
calc AS(SELECT b.*,COALESCE(cr.completed,0) completed,COALESCE(b.watched/NULLIF(t.watched,0),0) aud,COALESCE(b.produced/NULLIF(t.produced,0),0) prod FROM base b JOIN totals t USING(kind) LEFT JOIN completion_rates cr ON cr.cid=b.cid)
SELECT kind,owner,cid,heading,round(watched,2),produced,round(completed,4),round(aud,6),round(prod,6),round(s.audience_weight*aud+s.production_weight*prod+s.completion_weight*completed,6),round((s.audience_weight*aud+s.production_weight*prod+s.completion_weight*completed)*r.total*CASE WHEN kind='professor' THEN .25 ELSE .10 END)::bigint FROM calc,settings s,revenue r WHERE (kind='professor' AND owner=auth.uid() AND public.current_profile_role()='professor') OR (kind='ies' AND public.organization_member(owner,'ies')) OR (public.is_admin() AND public.current_profile_role() NOT IN('professor','ies','empresa','colaborador')) $$;
CREATE OR REPLACE FUNCTION public.close_month(_month date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total bigint; s public.fund_settings; BEGIN IF NOT public.is_admin() OR public.current_profile_role() IN('professor','ies','empresa','colaborador') THEN RAISE EXCEPTION 'Fechamento administrativo necessário'; END IF; IF date_trunc('month',_month)::date<>_month OR _month>=date_trunc('month',now())::date THEN RAISE EXCEPTION 'Feche somente meses encerrados'; END IF; SELECT COALESCE(sum(amount_cents),0) INTO total FROM public.payments WHERE status='pago' AND paid_at>=_month AND paid_at<(_month+interval '1 month'); SELECT * INTO s FROM public.fund_settings; INSERT INTO public.monthly_funds VALUES(_month,total,round(total*.25),round(total*.10),to_jsonb(s),now()); INSERT INTO public.author_scores(month,owner_id,fund_type,audience,production,completion,final_score,amount_cents) SELECT _month,owner_id,fund_type,sum(audience),sum(production),avg(completion),sum(audience)*s.audience_weight+sum(production)*s.production_weight+avg(completion)*s.completion_weight,round((sum(audience)*s.audience_weight+sum(production)*s.production_weight+avg(completion)*s.completion_weight)*total*CASE WHEN fund_type='professor' THEN .25 ELSE .10 END)::bigint FROM public.author_metrics(_month) GROUP BY fund_type,owner_id; END $$;
CREATE OR REPLACE FUNCTION public.mark_author_payment(_id uuid,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.author_scores; BEGIN IF NOT public.is_admin() OR public.current_profile_role() IN('professor','ies','empresa','colaborador') OR length(trim(_reference))<3 THEN RAISE EXCEPTION 'Pagamento não autorizado'; END IF; SELECT * INTO a FROM public.author_scores WHERE id=_id FOR UPDATE; IF NOT FOUND OR a.payment_status='pago' THEN RAISE EXCEPTION 'Pagamento indisponível'; END IF; UPDATE public.author_scores SET payment_status='pago' WHERE id=_id; INSERT INTO public.activity_logs(user_id,action,entity,meta) VALUES(auth.uid(),'repasse_registrado','author_scores',jsonb_build_object('score_id',_id,'reference',_reference)); END $$;
REVOKE ALL ON FUNCTION public.author_metrics(date),public.close_month(date),public.mark_author_payment(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.author_metrics(date),public.close_month(date),public.mark_author_payment(uuid,text) TO authenticated;